19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.Locale;
23	
24	/**
25	 * Derives an owner's {@code identityKey}: the full lower-case hexadecimal SHA-256 digest of
26	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. The telephone is
27	 * expected to already be in its normalized (E.164) form; the email is lower-cased and the last
28	 * name is reduced to its American Soundex code here, so two owners whose surnames sound alike
29	 * share the {@code soundex(lastName)} component. A {@code null} telephone or email contributes the
30	 * empty string. This single key drives both duplicate detection (a 409 on an exact key match) and
31	 * the {@code identityKey} field returned on the owner representation.
32	 */
33	public final class IdentityKey {
34	
35	    private IdentityKey() {
36	    }
37	
38	    /**
39	     * Builds the {@code identityKey} from an owner's normalized telephone, email and last name. The
40	     * telephone is used as-is (empty when {@code null}), the email is lower-cased (empty when
41	     * {@code null}) and the last name is reduced to its Soundex code, then the three parts are joined
42	     * with {@code '|'} and hashed with SHA-256.
43	     */
44	    public static String of(String telephone, String email, String lastName) {
45	        String tel = telephone == null ? "" : telephone;
46	        String mail = email == null ? "" : email.toLowerCase(Locale.ROOT);
47	        return sha256Hex(tel + "|" + mail + "|" + soundex(lastName));
48	    }
49	
50	    /**
51	     * Returns the American Soundex code of {@code value}: the upper-cased first letter followed by
52	     * three digits derived from the remaining letters (B,F,P,V-&gt;1; C,G,J,K,Q,S,X,Z-&gt;2; D,T-&gt;3;
53	     * L-&gt;4; M,N-&gt;5; R-&gt;6). Vowels and {@code Y} separate codes; {@code H} and {@code W} do
54	     * not, so letters they separate are treated as adjacent. Adjacent letters mapping to the same
55	     * code are coded once. The result is padded with zeros / truncated to four characters. A value
56	     * with no letters (or {@code null}) yields the empty string.
57	     */
58	    public static String soundex(String value) {
59	        if (value == null) {
60	            return "";
61	        }
62	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
63	        if (letters.isEmpty()) {
64	            return "";
65	        }
66	        StringBuilder code = new StringBuilder();
67	        code.append(letters.charAt(0));
68	        char previous = digitFor(letters.charAt(0));
69	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
70	            char letter = letters.charAt(i);
71	            if (letter == 'H' || letter == 'W') {
72	                continue;
73	            }
74	            char digit = digitFor(letter);
75	            if (digit != '0' && digit != previous) {
76	                code.append(digit);
77	            }
78	            previous = digit;
79	        }
80	        while (code.length() < 4) {
81	            code.append('0');
82	        }
83	        return code.substring(0, 4);
84	    }
85	
86	    /**
87	     * Maps a single upper-case letter to its Soundex digit, or {@code '0'} for a letter that is not
88	     * coded (a vowel, {@code Y}, {@code H} or {@code W}).
89	     */
90	    private static char digitFor(char letter) {
91	        return switch (letter) {
92	            case 'B', 'F', 'P', 'V' -> '1';
93	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
94	            case 'D', 'T' -> '3';
95	            case 'L' -> '4';
96	            case 'M', 'N' -> '5';
97	            case 'R' -> '6';
98	            default -> '0';
99	        };
100	    }
101	
102	    /**
103	     * Returns the full SHA-256 digest of {@code input}, rendered as lower-case hexadecimal.
104	     */
105	    private static String sha256Hex(String input) {
106	        try {
107	            byte[] digest = MessageDigest.getInstance("SHA-256")
108	                .digest(input.getBytes(StandardCharsets.UTF_8));
109	            StringBuilder hex = new StringBuilder(digest.length * 2);
110	            for (byte b : digest) {
111	                hex.append(String.format("%02x", b));
112	            }
113	            return hex.toString();
114	        } catch (NoSuchAlgorithmException ex) {
115	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
116	        }
117	    }
118	}
