5	/**
6	 * Derives an owner's marketing segment, formatted {@code '<TIER>_<AREA>'}.
7	 *
8	 * <p>The tier is {@code "PREMIUM"} when the {@code membershipLevel} is 3 or more, otherwise
9	 * {@code "STANDARD"} (including when the level is absent). The area is {@code "METRO"} when the
10	 * {@code locality} is a known region (NSW, VIC or QLD), otherwise {@code "REGIONAL"}. The two are
11	 * joined with an underscore, yielding one of {@code "PREMIUM_METRO"}, {@code "PREMIUM_REGIONAL"},
12	 * {@code "STANDARD_METRO"} or {@code "STANDARD_REGIONAL"}.
13	 *
14	 * <p>Kept as a standalone helper rather than a method on {@link OwnerMapper}: a single-argument
15	 * method declared on a MapStruct mapper would be picked up as an implicit conversion and applied to
16	 * every matching property mapping.
17	 */
18	public final class OwnerSegment {
19	
20	    /** Localities that count as METRO. */
21	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
22	
23	    private OwnerSegment() {
24	    }
25	
26	    /**
27	     * Returns the {@code '<TIER>_<AREA>'} segment for {@code membershipLevel} and {@code locality}.
28	     */
29	    public static String of(Integer membershipLevel, String locality) {
30	        String tier = membershipLevel != null && membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
31	        String area = locality != null && METRO_REGIONS.contains(locality) ? "METRO" : "REGIONAL";
32	        return tier + "_" + area;
33	    }
34	}
