1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's locality (region) from the postcode and city.
7	 *
8	 * <p>The postcode is preferred: a 4-digit postcode falling in a known region range (NSW 2000-2099,
9	 * VIC 3000-3099, QLD 4000-4099) fixes the region and disambiguates cities that share a name. Only
10	 * when the postcode is absent or in no known range does derivation fall back to the fixed
11	 * city-to-region table.
12	 *
13	 * <p>Kept as a standalone helper rather than a method on {@link OwnerMapper}: a single-argument
14	 * {@code String}-to-{@code String} method declared on a MapStruct mapper would be picked up as an
15	 * implicit conversion and applied to every String property mapping.
16	 */
17	public final class OwnerLocality {
18	
19	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
20	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
21	        "NSW", new int[] {2000, 2099},
22	        "VIC", new int[] {3000, 3099},
23	        "QLD", new int[] {4000, 4099});
24	
25	    /** Region -&gt; IANA timezone name. */
26	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
27	        "NSW", "Australia/Sydney",
28	        "VIC", "Australia/Melbourne",
29	        "QLD", "Australia/Brisbane");
30	
31	    private OwnerLocality() {
32	    }
33	
34	    /**
35	     * Returns the canonical region, preferring the {@code postcode}: a postcode in a known region
36	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) selects that region. When the postcode is
37	     * absent, malformed, or in no known range, falls back to the city-to-region table via
38	     * {@link #derive(String)}.
39	     */
40	    public static String derive(String city, String postcode) {
41	        String fromPostcode = regionForPostcode(postcode);
42	        if (fromPostcode != null) {
43	            return fromPostcode;
44	        }
45	        return derive(city);
46	    }
47	
48	    /**
49	     * Returns the canonical region for {@code city} (Sydney-&gt;NSW, Melbourne-&gt;VIC,
50	     * Brisbane-&gt;QLD), or {@code "UNKNOWN"} when the city is not in the table.
51	     */
52	    public static String derive(String city) {
53	        if (city == null) {
54	            return "UNKNOWN";
55	        }
56	        switch (city) {
57	            case "Sydney":
58	                return "NSW";
59	            case "Melbourne":
60	                return "VIC";
61	            case "Brisbane":
62	                return "QLD";
63	            default:
64	                return "UNKNOWN";
65	        }
66	    }
67	
68	    /**
69	     * Returns the region an owner's identity resolves to by reading it back off the {@code memberId},
70	     * which is formatted {@code '<REGION><FY><HASH8><CHK>'}: the leading REGION segment. The locality
71	     * therefore shares the single region-and-hash identity assigned at creation instead of being
72	     * recomputed from the city and postcode. A known region ({@code NSW}, {@code VIC} or {@code QLD})
73	     * is matched as the member id's prefix; any other member id - including one assigned to an owner
74	     * whose region derived to {@code "UNKNOWN"} - resolves to {@code "UNKNOWN"}, as does an absent or
75	     * blank value.
76	     */
77	    public static String fromMemberId(String memberId) {
78	        if (memberId == null || memberId.isBlank()) {
79	            return "UNKNOWN";
80	        }
81	        for (String region : REGION_TIMEZONE.keySet()) {
82	            if (memberId.startsWith(region)) {
83	                return region;
84	            }
85	        }
86	        return "UNKNOWN";
87	    }
88	
89	    /**
90	     * Returns the IANA timezone name for {@code region} via the fixed region-to-timezone table
91	     * (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne, QLD-&gt;Australia/Brisbane), or
92	     * {@code null} when the region is absent or not in the table.
93	     */
94	    public static String timezoneForRegion(String region) {
95	        return region == null ? null : REGION_TIMEZONE.get(region);
96	    }
97	
98	    /** Region for a 4-digit {@code postcode} in a known range, or {@code null} otherwise. */
99	    private static String regionForPostcode(String postcode) {
100	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
101	            return null;
102	        }
103	        int value = Integer.parseInt(postcode);
