82	    /**
83	     * Dedicated audit logger. On a successful create an audit line carrying the new owner's id,
84	     * {@code memberId}, {@code registrationDate} and {@code membershipLevel} is emitted to the
85	     * logger named {@code AUDIT}.
86	     */
87	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
88	
89	    /**
90	     * Dedicated notification logger. On a successful create a welcome notification carrying the new
91	     * owner's id and {@code memberId} is enqueued by emitting a line to the logger named
92	     * {@code NOTIFY}.
93	     */
94	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
95	
96	    /**
97	     * Monotonically increasing sequence number stamped onto each structured {@link OwnerCreatedEvent}.
98	     * Shared across all creates so the events carry a total order independent of the owner id.
99	     */
100	    private static final AtomicLong AUDIT_SEQUENCE = new AtomicLong();
101	
102	    /**
103	     * Syntactic check for an email address: a non-empty local part, an {@code @}, and a domain with
104	     * at least one dot and no whitespace on either side.
105	     */
106	    private static final Pattern EMAIL_PATTERN =
107	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
108	
109	    /**
110	     * Disposable email domains that an owner's email may not use. An email whose domain (the part
111	     * after the {@code @}, compared case-insensitively) is on this list is rejected with a 400
112	     * response naming {@code email}.
113	     */
114	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
115	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
116	
117	    /**
118	     * Common street-type abbreviations expanded during address normalization. Keys are the
119	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
120	     * expanded form.
121	     */
122	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
123	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
124	
125	    /**
126	     * Required national-number length per E.164 country code (the digits that follow the country
127	     * code). {@code '+61'} (Australia) requires 9 national digits; {@code '+1'} (NANP) requires 10.
128	     * A country code that is not listed here is not length-checked, keeping other numbers accepted.
129	     */
130	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH =
131	        Map.of("1", 10, "61", 9);
132	
133	    /**
134	     * Inclusive 4-digit postcode range allowed for each known region, keyed by the region an owner's
135	     * city derives to (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD): NSW 2000-2099, VIC
136	     * 3000-3099, QLD 4000-4099. A city that derives to no known region ({@code "UNKNOWN"}) is not in
137	     * this table and accepts any 4-digit postcode.
138	     */
139	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
140	        "NSW", new int[] {2000, 2099},
141	        "VIC", new int[] {3000, 3099},
142	        "QLD", new int[] {4000, 4099});
