614	    /**
615	     * Derives an already-stored owner's {@code identityKey} for duplicate comparison: the stored
616	     * telephone is converted to E.164 form (or the empty string when it cannot form a valid number),
617	     * the stored email is lower-cased and the stored last name is reduced to its Soundex code, exactly
618	     * as {@link IdentityKey#of} does for an incoming request.
619	     */
620	    private static String existingIdentityKey(Owner existing) {
621	        String telephone = orEmpty(normalizeExisting(existing.getTelephone()));
622	        return IdentityKey.of(telephone, existing.getEmail(), existing.getLastName());
623	    }
