690	    /**
691	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
692	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
693	     * written back onto the request so that is what gets stored and returned. A present but invalid
694	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
695	     */
696	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
697	        String email = ownerFieldsDto.getEmail();
698	        if (email == null) {
699	            return;
700	        }
701	        String trimmed = email.trim();
702	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
703	            throw new InvalidOwnerFieldsException(List.of("email"));
704	        }
705	        String normalized = trimmed.toLowerCase(Locale.ROOT);
706	        String domain = normalized.substring(normalized.indexOf('@') + 1);
707	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
