793	    /**
794	     * Assigns the owner's unified {@code memberId} on create, formatted
795	     * {@code '<REGION><FY><HASH8><CHK>'} where {@code REGION} is the region the owner's identity
796	     * derives to from its postcode (falling back to the city table when the postcode is absent or in
797	     * no known range), {@code FY} is the two-digit fiscal year of the business-day-adjusted
798	     * {@code registrationDate} (the fiscal year starts on 1 July, e.g. a registration on 2026-08-03
799	     * falls in fiscal year 2027 and yields {@code '27'}), {@code HASH8} is the first eight upper-case
800	     * hex characters of the SHA-256 digest of the normalized telephone concatenated with the last
801	     * name, and {@code CHK} is a single Luhn check digit over the digits of the
802	     * {@code '<REGION><FY><HASH8>'} body (e.g. {@code 'NSW271A2B3C4D4'}). The telephone has already
803	     * been normalized to E.164 form by {@link #normalizeTelephone} and {@code registrationDate} has
804	     * been defaulted, so both inputs are present. The identity is a pure function of region, fiscal
805	     * year, telephone and last name; the check digit is computed over the body before any
806	     * collision-handling suffix is applied.
807	     */
808	    private void assignMemberId(Owner owner) {
809	        String region = OwnerLocality.derive(owner.getCity(), owner.getPostcode());
810	        String fy = String.format("%02d", FiscalYear.yearOf(owner.getRegistrationDate()) % 100);
811	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName(), 8);
812	        String body = region + fy + hash8;
813	        int chk = MemberIdCheckDigit.of(body);
814	        owner.setMemberId(deduplicateMemberId(body + chk));
815	    }
