817	    /**
818	     * Returns {@code memberId} unchanged when no existing owner already carries it; otherwise appends
819	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not held by any
820	     * existing owner. Compared against the pre-existing owners, so the returned member id is unique
821	     * among them.
822	     */
823	    private String deduplicateMemberId(String memberId) {
824	        Set<String> existing = new HashSet<>();
825	        for (Owner owner : this.clinicService.findAllOwners()) {
826	            if (owner.getMemberId() != null) {
827	                existing.add(owner.getMemberId());
828	            }
829	        }
830	        if (!existing.contains(memberId)) {
831	            return memberId;
832	        }
833	        int n = 2;
834	        while (existing.contains(memberId + "-" + n)) {
835	            n++;
836	        }
837	        return memberId + "-" + n;
838	    }
