846	        String firstName = owner.getFirstName();
847	        String lastName = owner.getLastName();
848	        int count = 0;
849	        for (Owner existing : this.clinicService.findAllOwners()) {
850	            if (firstName.equalsIgnoreCase(existing.getFirstName())
851	                && lastName.equalsIgnoreCase(existing.getLastName())) {
