858	    /**
859	     * Assigns the new owner's {@code membershipPoints} and derived {@code membershipLevel} on create.
860	     * Points start at 0 and accrue: plus 2 when an email is present, plus 1 when {@code namesakeCount}
861	     * is 0, plus 2 for a household of 3 or more members, and plus 3 for tenure exceeding
862	     * {@value #TENURE_LEVEL_THRESHOLD_FISCAL_YEARS} elapsed fiscal year. The points are then mapped to a level of 1 (0-1
863	     * points), 2 (2-3), 3 (4-5), or 4 (6 or more). Runs after {@link #assignNamesakeCount} and
864	     * {@link #assignHouseholdMembership} so those counts are settled. A newly created owner has zero
865	     * tenure, so the tenure bonus never applies on create.
866	     */
867	    private void assignMembership(Owner owner) {
868	        int points = 0;
869	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
870	            points += 2;
871	        }
872	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
873	            points += 1;
874	        }
875	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
876	            points += 2;
877	        }
878	        if (tenureFiscalYears(owner) > TENURE_LEVEL_THRESHOLD_FISCAL_YEARS) {
879	            points += 3;
880	        }
881	        owner.setMembershipPoints(points);
882	        owner.setMembershipLevel(capMembershipLevelByHousehold(owner, membershipLevelForPoints(points)));
883	    }
