885	    /**
886	     * Caps a newly derived {@code membershipLevel} so it cannot exceed one above the current maximum
887	     * {@code membershipLevel} among the new owner's existing household members - the pre-existing owners
888	     * already carrying the same {@code householdId}. When the owner belongs to no household, or has no
889	     * existing household member, no cap applies and the derived level is returned unchanged. Runs after
890	     * {@link #assignHouseholdMembership} so the owner's {@code householdId} is settled.
891	     */
892	    private int capMembershipLevelByHousehold(Owner owner, int derivedLevel) {
893	        String householdId = owner.getHouseholdId();
894	        if (householdId == null || householdId.isBlank()) {
895	            return derivedLevel;
896	        }
897	        Integer maxHouseholdLevel = null;
898	        for (Owner existing : this.clinicService.findAllOwners()) {
899	            if (householdId.equals(existing.getHouseholdId()) && existing.getMembershipLevel() != null
900	                && (maxHouseholdLevel == null || existing.getMembershipLevel() > maxHouseholdLevel)) {
901	                maxHouseholdLevel = existing.getMembershipLevel();
902	            }
903	        }
904	        if (maxHouseholdLevel == null) {
905	            return derivedLevel;
906	        }
907	        return Math.min(derivedLevel, maxHouseholdLevel + 1);
908	    }
