910	    /**
911	     * Maps {@code membershipPoints} to a {@code membershipLevel}: 1 for 0-1 points, 2 for 2-3, 3 for
912	     * 4-5, and 4 for 6 or more points.
913	     */
914	    private int membershipLevelForPoints(int points) {
915	        if (points <= 1) {
916	            return 1;
917	        }
918	        if (points <= 3) {
919	            return 2;
920	        }
921	        if (points <= 5) {
922	            return 3;
923	        }
924	        return 4;
925	    }
