952	    }
953	
954	    /**
955	     * Assigns the new owner's {@code capacityWarning} on create: {@code true} when the owner's city
956	     * already holds between {@value #CAPACITY_WARNING_THRESHOLD} and {@value #MAX_OWNERS_PER_CITY}
957	     * minus one owners (approaching the {@value #MAX_OWNERS_PER_CITY} capacity limit), otherwise
958	     * {@code false}. Existing owners are counted case-insensitively on {@code city}, the same way
959	     * {@link #rejectCityAtCapacity} counts them, and computed before the new owner is persisted so it
960	     * counts only the pre-existing owners. A city at or over the hard limit has already been rejected
961	     * by {@link #rejectCityAtCapacity}, so this only ever sees counts below the limit.
962	     */
963	    private void assignCapacityWarning(Owner owner) {
964	        String city = owner.getCity();
965	        int count = 0;
966	        for (Owner existing : this.clinicService.findAllOwners()) {
967	            if (city.equalsIgnoreCase(existing.getCity())) {
968	                count++;
969	            }
970	        }
971	        owner.setCapacityWarning(count >= CAPACITY_WARNING_THRESHOLD && count < MAX_OWNERS_PER_CITY);
972	    }
973	
974	    /**
975	     * Assigns the new owner's {@code possibleDuplicate} / {@code possibleDuplicateOf} on create. The
976	     * owner has already cleared the duplicate block, so it is not a hard duplicate. It is flagged as a
977	     * possible duplicate when an existing owner has the same {@code soundex(lastName)} and the same
978	     * {@code postcode} (a present, exact match) yet a <em>different</em> {@code identityKey} - the
979	     * soft-match now keys on the surname sound and postcode rather than an exact last name, and fires
980	     * precisely for the near-miss the identity key lets through (same household surname and postcode
981	     * but a different telephone, so a different key). When such an owner exists,
982	     * {@code possibleDuplicate} is set to {@code true} and {@code possibleDuplicateOf} to that owner's
983	     * id (the lowest id when several match); otherwise {@code possibleDuplicate} is {@code false} and
984	     * {@code possibleDuplicateOf} is left {@code null}. Computed before the new owner is persisted, so
985	     * it considers only the pre-existing owners.
986	     *
987	     * <p>A declared household member ({@code sharesHousehold} set to {@code true}) is never flagged: it
988	     * has deliberately opted into an existing household, so its shared last name and postcode are
989	     * expected rather than a suspected duplicate.
990	     */
991	    private void assignPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
992	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
993	            owner.setPossibleDuplicate(false);
994	            owner.setPossibleDuplicateOf(null);
995	            return;
996	        }
997	        String postcode = owner.getPostcode();
998	        String soundex = IdentityKey.soundex(owner.getLastName());
999	        String identityKey = IdentityKey.of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
1000	        Integer matchId = null;
1001	        if (postcode != null && !postcode.isBlank()) {
1002	            for (Owner existing : this.clinicService.findAllOwners()) {
1003	                if (soundex.equals(IdentityKey.soundex(existing.getLastName()))
1004	                    && postcode.equals(existing.getPostcode())
1005	                    && !identityKey.equals(existingIdentityKey(existing))
1006	                    && existing.getId() != null
1007	                    && (matchId == null || existing.getId() < matchId)) {
1008	                    matchId = existing.getId();
1009	                }
1010	            }
1011	        }
1012	        owner.setPossibleDuplicate(matchId != null);
1013	        owner.setPossibleDuplicateOf(matchId);
1014	    }
1015	
1016	    /**
1017	     * Computes the new owner's deterministic {@code householdId}: the first twelve upper-case hex
1018	     * characters of the SHA-256 digest of {@code "<normalizedLastName>|<postcode>"}, where the last
1019	     * name is normalized for comparison (trimmed, internal whitespace collapsed, lower-cased) and the
1020	     * postcode is the already-validated 4-digit value. Because it is a pure function of the last name
1021	     * and postcode, any two owners sharing those - regardless of creation order or whether they opted
1022	     * into {@code sharesHousehold} - land in the same household automatically. Returns {@code null}
1023	     * when the owner has no postcode, so such owners belong to no household. This single value feeds
1024	     * both the duplicate detection ({@link #rejectDuplicate}) and the household-size count
1025	     * ({@link #assignHouseholdMembership}).
1026	     */
1027	    private String computeHouseholdId(OwnerFieldsDto ownerFieldsDto) {
1028	        String postcode = ownerFieldsDto.getPostcode();
1029	        if (postcode == null || postcode.isBlank()) {
1030	            return null;
1031	        }
1032	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
1033	        return shaHexUpper(lastName + "|" + postcode, 12);
1034	    }
1035	
1036	    /**
1037	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
1038	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
1039	     * every existing owner already carrying the same identifier. Runs after the owner's
1040	     * {@code householdId} has been set from {@link #computeHouseholdId} so the identifier is settled.
1041	     * Left {@code null} when the owner belongs to no household.
1042	     */
1043	    private void assignHouseholdMembership(Owner owner) {
1044	        String householdId = owner.getHouseholdId();
1045	        if (householdId == null || householdId.isBlank()) {
1046	            owner.setHouseholdMemberCount(null);
1047	            return;
1048	        }
1049	        int count = 1;
1050	        for (Owner existing : this.clinicService.findAllOwners()) {
1051	            if (householdId.equals(existing.getHouseholdId())) {
1052	                count++;
1053	            }
1054	        }
1055	        owner.setHouseholdMemberCount(count);
1056	    }
1057	
1058	    /**
1059	     * Returns the first {@code length} characters of the SHA-256 digest of {@code input}, rendered as
1060	     * upper-case hexadecimal. Used to derive the {@code memberId} HASH8 segment and the household
1061	     * identifier, both stable functions of their inputs.
1062	     */
1063	    private static String shaHexUpper(String input, int length) {
1064	        try {
1065	            byte[] digest = MessageDigest.getInstance("SHA-256")
1066	                .digest(input.getBytes(StandardCharsets.UTF_8));
1067	            StringBuilder hex = new StringBuilder(digest.length * 2);
1068	            for (byte b : digest) {
1069	                hex.append(String.format("%02x", b));
1070	            }
1071	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
1072	        } catch (NoSuchAlgorithmException ex) {
1073	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
1074	        }
1075	    }
1076	}
